<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { useListPersistence } from '../composables/useListPersistence'

const router = useRouter()
const listPersistence = useListPersistence('ListMarketing')

// Klik card CMO → buka pemilih FID/FPD, scoped ke marketing tsb (via query).
// m  = id_marketing (dipakai scope FID/FPD); mu = user_id/email (dipakai filter
// field `marketing` di Data Pengajuan); nm = nama untuk tampilan.
function goToFidFpd(row) {
	if (!row?.id_marketing) return
	router.push({
		name: 'FidFpdChooser',
		query: { m: row.id_marketing, nm: row.nama_lengkap || '', mu: row.name || '' },
	})
}

// ---- Data & pagination ----------------------------------------------------
const PAGE_LEN = 20
const start = ref(0)
const rows = ref([])
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

// ---- Sort (bottom-sheet) --------------------------------------------------
const SORT_FIELDS = [
	{ key: 'nama_lengkap', label: 'Nama Marketing' },
	{ key: 'id_marketing', label: 'ID Marketing' },
	{ key: 'cabang', label: 'Cabang' },
]
const sortField = ref('nama_lengkap')
const sortDir = ref('asc')

const showSortSheet = ref(false)
const sortFieldDraft = ref(sortField.value)
const sortDirDraft = ref(sortDir.value)
function openSort() {
	sortFieldDraft.value = sortField.value
	sortDirDraft.value = sortDir.value
	showSortSheet.value = true
}
function pickSortField(key) {
	sortFieldDraft.value = key
}
function toggleSortDirDraft() {
	sortDirDraft.value = sortDirDraft.value === 'asc' ? 'desc' : 'asc'
}
function applySort() {
	sortField.value = sortFieldDraft.value
	sortDir.value = sortDirDraft.value
	listPersistence.writePreferences({ sortField: sortField.value, sortDir: sortDir.value })
	showSortSheet.value = false
	reload()
}

// ---- Filter (bottom-sheet) ------------------------------------------------
// Semua field teks pakai operator `like`. NB: nilai dikirim MENTAH — backend
// (get_marketing_list) yang membungkus '%...%', jadi tidak ada double-wrap.
function blankFilter() {
	return { nama_lengkap: '', id_marketing: '', cabang: '' }
}
const filterDraft = reactive(blankFilter()) // working copy saat sheet terbuka
const appliedFilter = reactive(blankFilter()) // yang sudah diterapkan ke query

const showFilterSheet = ref(false)
function openFilter() {
	Object.assign(filterDraft, appliedFilter)
	showFilterSheet.value = true
}
function applyFilter() {
	Object.assign(appliedFilter, filterDraft)
	listPersistence.writeSession({ filters: appliedFilter })
	showFilterSheet.value = false
	reload()
}
function clearFilter() {
	Object.assign(filterDraft, blankFilter())
	Object.assign(appliedFilter, blankFilter())
	listPersistence.clearSession()
	showFilterSheet.value = false
	reload()
}

// Jumlah field filter aktif (untuk badge angka di tombol filter header).
const activeFilterCount = computed(
	() => Object.values(appliedFilter).filter((v) => String(v).trim()).length,
)

// Filter AND yang dikirim ke get_marketing_list.
function buildFilters() {
	const arr = []
	const f = appliedFilter
	for (const key of ['nama_lengkap', 'id_marketing', 'cabang']) {
		const v = String(f[key] || '').trim()
		if (v) arr.push([key, 'like', v])
	}
	return arr
}

// ---- Fetch ----------------------------------------------------------------
// Endpoint khusus: scope cabang Pimcab + filter `cmo=1` dilakukan di server.
// Mengembalikan { rows, total } (total hanya saat start==0).
const list = createResource({
	url: 'juragan.api.portal.list_marketing.get_marketing_list',
	makeParams() {
		const params = {
			start: start.value,
			page_length: PAGE_LEN,
			order_by: `${sortField.value} ${sortDir.value}`,
		}
		const andF = buildFilters()
		if (andF.length) params.filters = JSON.stringify(andF)
		return params
	},
	auto: false,
	onSuccess(data) {
		const batch = (data && data.rows) || []
		// start 0 = query baru (replace); selain itu = Load more (append).
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PAGE_LEN
		loading.value = false
	},
	onError(err) {
		error.value = err?.message || String(err)
		loading.value = false
	},
})

// Reload dari awal (reset start).
function reload() {
	start.value = 0
	error.value = ''
	loading.value = true
	list.fetch()
}

function loadMore() {
	start.value += PAGE_LEN
	loading.value = true
	list.fetch()
}

onMounted(async () => {
	await refreshCsrfToken()
	Object.assign(appliedFilter, listPersistence.readSession({ filters: blankFilter() }).filters)
	const prefs = listPersistence.readPreferences({ sortField: 'nama_lengkap', sortDir: 'asc' })
	if (SORT_FIELDS.some((field) => field.key === prefs.sortField))
		sortField.value = prefs.sortField
	if (['asc', 'desc'].includes(prefs.sortDir)) sortDir.value = prefs.sortDir
	reload()
})
</script>

